    # Extract the central cell-pattern patch that repeats in the outer wallpaper.
    holes = [(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v == 0]
    if not holes:
        return [row[:] for row in grid]
    r0,r1=min(r for r,c in holes),max(r for r,c in holes)
    c0,c1=min(c for r,c in holes),max(c for r,c in holes)
    h,w=r1-r0+1,c1-c0+1
    # Use the repeated instance whose surroundings most closely match the hole's.
    best=None
    for rr in range(len(grid)-h+1):
      for cc in range(len(grid[0])-w+1):
        if rr==r0 and cc==c0: continue
        if any(grid[rr+i][cc+j]==0 for i in range(h) for j in range(w)): continue
        score=0
        for i in range(h):
          for j in range(w):
            v=grid[rr+i][cc+j]
            # Compare each candidate cell with all values at the same relative
            # position in the other repeated tiles.
            for ar,ac in ((rr+i-12,cc+j),(rr+i+12,cc+j),(rr+i,cc+j-12),(rr+i,cc+j+12)):
              if 0<=ar<len(grid) and 0<=ac<len(grid[0]) and grid[ar][ac]==v: score+=1
        rank=(score,-abs(rr-r0)-abs(cc-c0))
        if best is None or rank>best[0]: best=(rank,rr,cc)
    if best:
      _,rr,cc=best
      return [grid[rr+i][cc:cc+w] for i in range(h)]
    return [[grid[r0+i][c0+j] for j in range(w)] for i in range(h)]
